checks:
assert topological([('a','c'),('b','c'),('a','c')], ['c','b','a','d']) == ['a','b','c','d']
try: topological([('a','b'),('b','a')], ['a','b'])
except ValueError: pass
else: raise AssertionError('cycle')

assert decode_runs('12a2b') == 'a'*12+'bb'
assert decode_runs('') == ''
for s in ['0a','a','3','2A','2é','1a!']:
 try: decode_runs(s)
 except ValueError: pass
 else: raise AssertionError(s)

assert window_max([1,3,-1,-3,5,3,6,7],3) == [3,3,5,5,6,7]
assert window_max([2,2],1) == [2,2]
assert window_max([],2) == []
try: window_max([1],0)
except ValueError: pass
else: raise AssertionError()

assert split_escaped(r'a\,b,c\\d,,') == ['a,b',r'c\d','','']
assert split_escaped('') == ['']
try: split_escaped('x'+chr(92))
except ValueError: pass
else: raise AssertionError()

v={'a/b':{'~x':[4,5]}}
assert json_pointer(v,'/a~1b/~0x/1') == 5
assert json_pointer(v,'') is v
for p in ['/a~2b','/a~1b/~0x/01','/a~1b/~0x/-1','x']:
 try: json_pointer(v,p)
 except ValueError: pass
 else: raise AssertionError(p)

assert parse_duration('2h3m4s') == 7384
assert parse_duration('0s') == 0
assert parse_duration('90m') == 5400
for x in ['', '1m1h','1s2s','2','-1s','1 h']:
 try: parse_duration(x)
 except ValueError: pass
 else: raise AssertionError(x)

assert apply_patch('abcdef',[(4,6,'Z'),(1,3,'X')]) == 'aXdZ'
assert apply_patch('abc',[(3,3,'!')]) == 'abc!'
for e in [[(0,2,'x'),(1,3,'y')],[(0,0,'x'),(0,1,'y')],[(2,1,'x')],[(0,4,'x')]]:
 try: apply_patch('abc',e)
 except ValueError: pass
 else: raise AssertionError(e)

assert expression('2 * -(3 + 4) + 10') == -4
assert expression('--2*3') == 6
assert expression(' 12 + (3*4) ') == 24
for s in ['','1 2','2+','(1','1/2','x']:
 try: expression(s)
 except ValueError: pass
 else: raise AssertionError(s)

assert retry_delays(5,0.5,2) == [0.5,1,2,2,2]
assert retry_delays(0,1,2) == []
assert retry_delays(3,4,2) == [2,2,2]
try: retry_delays(-1,1,2)
except ValueError: pass
else: raise AssertionError()

assert memo_cycle({'a':['b','b'],'b':['c'],'c':3,'x':['x']},'a') == 6
for d in [{'a':['a']},{'a':['b']}]:
 try: memo_cycle(d,'a')
 except ValueError: pass
 else: raise AssertionError()
